    SELECT id INTO v_id
    FROM catalogue_produits
    WHERE categorie = 'pac_air_eau' AND reference = p->>'reference'
    ORDER BY actif DESC, created_at NULLS LAST
    LIMIT 1;

    IF v_id IS NULL THEN
      INSERT INTO catalogue_produits (
        entreprise_id, categorie, nom, marque, reference, description, caracteristiques,
        prix_unitaire_ht, unite, tva_taux, eligible_mpr, eligible_cee, fiche_cee, actif,
        public_cible, catalogue_groupe, forfait_pose_ht, forfait_evacuation_ht
      ) VALUES (
        v_entreprise, 'pac_air_eau', p->>'nom', 'Hitachi', p->>'reference', p->>'description',
        p->'caracteristiques',
        COALESCE(NULLIF(p->>'prix_unitaire_ht','')::numeric, 0),
        'unite', 5.5, true, true, 'BAR-TH-171', true,
        'particulier', 'particulier', 0, 0
      );
      v_ajoutes := v_ajoutes + 1;
    ELSE
      UPDATE catalogue_produits SET
        nom = p->>'nom',
        marque = 'Hitachi',
        description = CASE
          WHEN COALESCE(btrim(description), '') = ''
            OR description = nom
            OR description = p->>'nom'
            OR description LIKE 'Pack PAC air/eau Hitachi%'
          THEN p->>'description'
          ELSE description
        END,
        caracteristiques = (COALESCE(caracteristiques, '{}'::jsonb)
                              - 'pose_non_fournie_dans_source'
                              - 'aides_a_verifier_sur_fiche_officielle'
                              - 'prix_a_renseigner')
                           || ((p->'caracteristiques') - 'prix_a_renseigner'::text),
        prix_unitaire_ht = COALESCE(NULLIF(p->>'prix_unitaire_ht','')::numeric, prix_unitaire_ht),
        tva_taux = 5.5,
        fiche_cee = 'BAR-TH-171',
        eligible_cee = true,
        eligible_mpr = true,
        actif = true,
        public_cible = 'particulier',
        catalogue_groupe = 'particulier'
      WHERE id = v_id;
      v_maj := v_maj + 1;
    END IF;
    v_id := NULL;
  END LOOP;

  -- Drapeau « prix à renseigner » : uniquement pour les packs Hitachi toujours sans prix.
  UPDATE catalogue_produits
  SET caracteristiques = CASE
    WHEN COALESCE(prix_unitaire_ht, 0) > 0 THEN caracteristiques - 'prix_a_renseigner'
    ELSE caracteristiques || '{"prix_a_renseigner": true}'::jsonb
  END
  WHERE categorie = 'pac_air_eau' AND marque = 'Hitachi' AND reference LIKE 'HITACHI-%';

  -- Fusion du doublon issu du fichier Excel du 20/10/2026.
  SELECT id INTO v_canon FROM catalogue_produits
  WHERE categorie = 'pac_air_eau' AND reference = 'HITACHI-RAS-4WHVRP2E-RWD-4_0RW3E-220S'
  ORDER BY actif DESC, created_at NULLS LAST LIMIT 1;

  IF v_canon IS NOT NULL THEN
    FOR v_dup IN
      SELECT id, forfait_pose_ht, forfait_evacuation_ht, caracteristiques
      FROM catalogue_produits
      WHERE categorie = 'pac_air_eau'
        AND id <> v_canon
        AND marque = 'Hitachi'
        AND reference = 'RAS-4WHVRP2E + RWD-4.0RW3E-220S'
    LOOP
      UPDATE catalogue_produits SET
        forfait_pose_ht = CASE WHEN COALESCE(forfait_pose_ht, 0) > 0 THEN forfait_pose_ht ELSE COALESCE(v_dup.forfait_pose_ht, 0) END,
        forfait_evacuation_ht = CASE WHEN COALESCE(forfait_evacuation_ht, 0) > 0 THEN forfait_evacuation_ht ELSE COALESCE(v_dup.forfait_evacuation_ht, 0) END,
        caracteristiques = (COALESCE(v_dup.caracteristiques, '{}'::jsonb)
                              - 'fiche_cee' - 'source_tarifs' - 'source_date'
                              - 'prix_fourniture_ht' - 'forfait_pose_ht')
                           || COALESCE(caracteristiques, '{}'::jsonb)
      WHERE id = v_canon;

      UPDATE catalogue_produits SET
        actif = false,
        caracteristiques = COALESCE(caracteristiques, '{}'::jsonb)
          || '{"doublon_de": "HITACHI-RAS-4WHVRP2E-RWD-4_0RW3E-220S"}'::jsonb
      WHERE id = v_dup.id;
      RAISE NOTICE 'Doublon Hitachi désactivé et fusionné : %', v_dup.id;
    END LOOP;
  END IF;

  RAISE NOTICE 'Hitachi : % pack(s) ajouté(s), % mis à jour', v_ajoutes, v_maj;
END $$;
